// ── fitHeight ────────────────────────────────────────────────────────────────

func numbered(prefix string, n int) string {
	lines := make([]string, n)
	for i := range lines {
		lines[i] = fmt.Sprintf("%s%d", prefix, i)
	}
	return strings.Join(lines, "\n")
}

func TestFitHeightLeavesAFittingStackAlone(t *testing.T) {
	got := fitHeight(numbered("h", 2), numbered("b", 2), numbered("f", 2), 10)
	if want := "h0\nh1\nb0\nb1\nf0\nf1"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestFitHeightCutsTheBodyBottomFirstThenKeepsHeaderAndFooter(t *testing.T) {
	got := fitHeight(numbered("h", 2), numbered("b", 4), numbered("f", 2), 6)
	if want := "h0\nh1\nb0\nb1\nf0\nf1"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
	// The body is gone entirely before the footer loses a line.
	got = fitHeight(numbered("h", 2), numbered("b", 4), numbered("f", 2), 4)
	if want := "h0\nh1\nf0\nf1"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestFitHeightCutsTheFooterBeforeTheHeaderWhenNoBodyIsLeft(t *testing.T) {
	got := fitHeight(numbered("h", 3), numbered("b", 2), numbered("f", 3), 4)
	if want := "h0\nh1\nh2\nf0"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestFitHeightWithAHeaderTallerThanTheTerminalKeepsItsFirstLines(t *testing.T) {
	got := fitHeight(numbered("h", 10), numbered("b", 3), numbered("f", 2), 4)
	if want := "h0\nh1\nh2\nh3"; got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestFitHeightNonPositiveHeightCutsNothing(t *testing.T) {
	for _, h := range []int{0, -3} {
		got := fitHeight(numbered("h", 2), numbered("b", 2), numbered("f", 2), h)
		if want := "h0\nh1\nb0\nb1\nf0\nf1"; got != want {
			t.Errorf("height %d: got %q, want %q", h, got, want)
		}
	}
}

// The input is inside the frame at every height from 9, and the footer's info
// line stays on screen while the free height V = H - 8 - footer is at least 3.
// Below that the frame may cover the footer; that is a documented floor.
func TestTheInputAndTheFooterSurviveShortTerminals(t *testing.T) {
package app

import (
	"os"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
	"github.com/anthnel/devdesk/internal/viewer"
)

// DEVDESK-457: whatever a view puts at the top of its footer, the frame above
// it must join it. The router reads the bar from the footer itself, so a view
// whose FilterBarVisible() disagrees with its RenderFooter() cannot leave a
// closed box sitting on top of an open one.

func isBox(l, left, right string) bool {
	return strings.HasPrefix(l, left) && strings.HasSuffix(l, right)
}

// assertBarAttached checks the screen as drawn: the right height, and no
// closed floor directly over a bar line. When a bar is on screen (a line that
func lineIndex(lines []string, prefix string) int {
	for i, l := range lines {
		if strings.HasPrefix(l, prefix) {
			return i
		}
	}
	return -1
}

func netdiagApp(t *testing.T, w, h int) *App {
	t.Helper()
	isolateHome(t)
	a := newWithSize(testConfig(), w, h)
	a.createView(command.ViewNetdiag)
	a.currentView = command.ViewNetdiag
	a.resize(w, h)
	return a
}

// feedView sends msgs to the active view directly, as the view tests do, so
// no Cmd is run, then lets the router re-measure the footer the way it does
// after every message.
func feedView(a *App, msgs ...tea.Msg) {
	for _, msg := range msgs {
		updated, _ := a.views[a.currentView].Update(msg)
		a.setView(a.currentView, updated)
	}
	a.resize(a.width, a.height)
}

func TestPathTabBarIsAttachedToTheFrame(t *testing.T) {
	for _, size := range []struct{ w, h int }{{200, 50}, {80, 16}} {
		a := netdiagApp(t, size.w, size.h)
		feedView(a, testutil.Keys("tab", "tab", "tab", "tab")...)

		lines := screen(a)
		assertJoined(t, lines, "│Target ›")
		assertBarAttached(t, lines, size.h)
	}
}

func TestInterfacesTabFilterBarIsAttachedToTheFrame(t *testing.T) {
	a := netdiagApp(t, 160, 40)
	feedView(a, testutil.Keys("tab", "tab")...)
	feedView(a, testutil.Key("/"))

	lines := screen(a)
	assertJoined(t, lines, "│ /")
	assertBarAttached(t, lines, 40)
}

